ALTER PROCEDURE [dbo].[Acc_ExecRep_09]   
AS

IF NOT EXISTS (    SELECT COUNT(*) FROM dbo.sysobjects
                                WHERE name in ('CustSetting','CustOverride','CustSetting3rd','CustOverride3rd')
                                    and xtype = 'U'
                                HAVING COUNT(*) = 4)
BEGIN
    RETURN
END

